import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.media.MediaPlayer;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.lang.ref.WeakReference;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
