 private static final int PICK=941,MIC=942;private static final ThreadPoolExecutor WORK=new ThreadPoolExecutor(0,1,1,TimeUnit.SECONDS,new LinkedBlockingQueue<Runnable>(2),r->{Thread t=new Thread(r,"YOnSoundBench");t.setDaemon(true);return t;});private static final AtomicReference<String> LATEST=new AtomicReference<>("");
 private final Handler main=new Handler(Looper.getMainLooper());private LinearLayout body,results;private ScrollView contentScroll;private TextView status,inputTitle;private Button start,stop,pick,play,save,mic,compare;private Uri input;private String modelId="yamnet-classifier",demoId="",group="ALL";private boolean compareAll=true,active,destroyed,exporting,microphoneInput,pendingMic;private OneComparisonPolicy.StartGate startGate;private Job current;private JSONObject last;private float[] lastWaveform;private double lastDuration;private MediaPlayer player;private boolean playbackClosed=true;
 @Override public void onCreate(Bundle state){super.onCreate(state);group=OneComparisonPolicy.group(state==null?getIntent().getStringExtra("group"):state.getString("group"));modelId=state==null?getIntent().getStringExtra("model_id"):state.getString("modelId");if(modelId==null||modelId.isEmpty())modelId=OneModels.selected(this,"sound",group);try{SoundEngine.expected(modelId);}catch(IllegalArgumentException e){modelId="yamnet-classifier";}demoId=getIntent().getStringExtra("demo_id");if(demoId==null)demoId="";compareAll=state==null?getIntent().getBooleanExtra("compare_all",true):state.getBoolean("compareAll",true);String uri=getIntent().getStringExtra("input_uri");input=uri==null?getIntent().getData():Uri.parse(uri);if(state!=null){String saved=state.getString("input");input=saved==null?null:Uri.parse(saved);demoId=state.getString("demo",demoId);}if(input!=null&&!"content".equals(input.getScheme()))input=null;startGate=new OneComparisonPolicy.StartGate(getIntent().getBooleanExtra("auto_start",false),state!=null,input!=null);build();if(state!=null){if(state.getBoolean("wasRunning",false))status.setText("이전 분석이 중단됐습니다 · 다시 시작하세요");else{JSONObject saved=Records.read(this,"sound-bench-result.json");if(saved!=null&&demoId.equals(saved.optString("demoId"))&&OneComparisonPolicy.canRestore(state.getString("runId",""),state.getString("inputSha",""),group,saved.optString("runId"),saved.optString("inputSha256"),saved.optString("group"),saved.optString("state"),saved.optBoolean("workerDone"))){last=saved;lastDuration=saved.optDouble("durationSec",0);render(last,null,lastDuration);status.setText("이전 모델 비교 결과");}}OneUi.restoreScroll(contentScroll,state.getFloat("scrollFraction",0));}}
 private void build(){LinearLayout frame=new LinearLayout(this);frame.setOrientation(1);frame.setBackgroundColor(Ui.BACK);LinearLayout header=Ui.brandHeader(this,"생활 소리 분석");header.addView(Ui.secondary(this,"닫기",v->finish()));frame.addView(header);ScrollView scroll=new ScrollView(this);contentScroll=scroll;body=Ui.column(this);scroll.addView(body);frame.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));body.addView(Ui.heading(this,"소리의 종류와 변화를 찾아보세요",25));status=Ui.text(this,"음성을 선택하면 같은 구간으로 모델을 비교합니다",15);body.addView(status);inputTitle=Ui.text(this,demoTitle(),16);body.addView(inputTitle);pick=Ui.secondary(this,"데모 · 내 음성",v->choose());start=Ui.button(this,"분석 시작",v->begin());compare=Ui.secondary(this,"모든 모델 비교",v->{compareAll=true;begin();});stop=Ui.secondary(this,"중지",v->cancel());play=Ui.secondary(this,"소리 듣기",v->play());save=Ui.secondary(this,"HTML · CSV · JSON 저장",v->export());mic=Ui.secondary(this,"주변 소리 분석 · 5초",v->OneDeviceSupport.microphone(this,()->microphone()));body.addView(Ui.actions(this,6,pick,start,compare,stop,play,mic,save),Ui.fill());results=new LinearLayout(this);results.setOrientation(1);body.addView(results,Ui.fill());setContentView(frame);actions();}
 @Override public void onConfigurationChanged(android.content.res.Configuration configuration){super.onConfigurationChanged(configuration);float position=OneUi.scrollFraction(contentScroll);String message=status.getText().toString(),label=inputTitle.getText().toString(),playLabel=play.getText().toString();build();if(last!=null)render(last,lastWaveform,lastDuration);status.setText(message);inputTitle.setText(label);play.setText(player==null?"소리 듣기":playLabel);actions();OneUi.restoreScroll(contentScroll,position);}
 private String demoTitle(){try{DemoStore.Item item=DemoStore.find(this,demoId);return item==null?input==null?"비·반려동물·기계음 등 다양한 소리를 골라보세요":"선택한 음성":item.title+" · "+item.group;}catch(Exception e){return "선택한 음성";}}
 @Override protected void onResume(){super.onResume();active=true;actions();if(pendingMic&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==android.content.pm.PackageManager.PERMISSION_GRANTED){microphone();return;}if(last!=null&&current==null)render(last,lastWaveform,lastDuration);if(startGate!=null&&startGate.take())begin();}
 @Override protected void onPause(){active=false;cancel();super.onPause();}
 @Override protected void onDestroy(){destroyed=true;cancel();super.onDestroy();}
 @Override protected void onSaveInstanceState(Bundle out){if(input!=null)out.putString("input",input.toString());out.putString("demo",demoId);out.putString("group",group);out.putString("modelId",modelId);out.putBoolean("compareAll",compareAll);out.putBoolean("wasRunning",current!=null);out.putString("runId",last==null?"":last.optString("runId"));out.putString("inputSha",last==null?"":last.optString("inputSha256"));out.putFloat("scrollFraction",OneUi.scrollFraction(contentScroll));super.onSaveInstanceState(out);}
 private void microphone(){if(current!=null||exporting)return;if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED){pendingMic=true;requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},MIC);return;}pendingMic=false;microphoneInput=true;input=null;demoId="";inputTitle.setText("주변 소리 · 5초");begin();}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==MIC&&pendingMic){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==android.content.pm.PackageManager.PERMISSION_GRANTED){if(active)main.post(()->{if(active)microphone();});}else{pendingMic=false;status.setText("마이크 접근을 허용해 주세요");}}}
 private void choose(){if(current!=null||exporting)return;if(startGate!=null)startGate.cancel();Intent intent=new Intent(this,DemoLibraryActivity.class).putExtra("feature","sound").putExtra("group",group).putExtra("media_type","audio");startActivityForResult(intent,PICK);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=PICK||result!=RESULT_OK||data==null)return;Uri uri=data.getData();if(uri==null||!"content".equals(uri.getScheme()))return;input=uri;microphoneInput=false;demoId=data.getStringExtra("demo_id");if(demoId==null)demoId="";if(startGate!=null)startGate.inputSelected(compareAll);last=null;lastWaveform=null;lastDuration=0;results.removeAllViews();inputTitle.setText(demoTitle());status.setText("비교할 모델과 분석 시작을 선택하세요");actions();if(active&&startGate!=null&&startGate.take())begin();}
 private void actions(){boolean busy=current!=null||exporting;pick.setEnabled(!busy);start.setEnabled(!busy&&(input!=null||microphoneInput));mic.setEnabled(!busy);compare.setEnabled(!busy&&(input!=null||microphoneInput));stop.setEnabled(current!=null||player!=null);play.setEnabled(!busy&&input!=null&&!microphoneInput);save.setEnabled(!busy&&last!=null&&last.optJSONArray("models")!=null&&last.optJSONArray("models").length()>0);}
 private void begin(){if(!active||destroyed||current!=null||exporting||(input==null&&!microphoneInput))return;if(startGate!=null)startGate.cancel();stopPlayback();results.removeAllViews();last=null;lastWaveform=null;lastDuration=0;List<String> ids=new ArrayList<>();if(compareAll){for(OneModels.Entry entry:OneModels.list(this,"sound",group))ids.add(entry.id);}else ids.add(modelId);if(ids.isEmpty())ids.add(modelId);Job job=new Job(getApplicationContext(),this,input,demoId,ids,microphoneInput);current=job;LATEST.set(job.id);status.setText("소리를 준비하고 있습니다");actions();try{WORK.execute(job);}catch(RejectedExecutionException e){current=null;status.setText("이전 분석을 마무리한 뒤 다시 시작하세요");actions();}}
 private void cancel(){Job job=current;if(job!=null){job.canceled.set(true);status.setText("분석을 마무리하는 중");}stopPlayback();actions();}
 private void stopPlayback(){MediaPlayer old=player;player=null;if(old!=null)try{old.reset();}finally{old.release();}playbackClosed=true;if(play!=null)play.setText("소리 듣기");playbackRecord();}
 private void playbackRecord(){if(last==null||!LATEST.get().equals(last.optString("runId")))return;try{last.put("playbackClosed",playbackClosed);Records.write(getApplicationContext(),"sound-bench-result.json",last);}catch(Exception e){android.util.Log.w("YOn","sound_playback_record",e);}}
 private void play(){if(player!=null){stopPlayback();actions();return;}if(input==null||current!=null)return;MediaPlayer next=new MediaPlayer();player=next;playbackClosed=false;playbackRecord();try{next.setDataSource(this,input);next.setOnPreparedListener(p->{if(player==p&&active){p.start();play.setText("듣기 중지");actions();}});next.setOnCompletionListener(p->{stopPlayback();actions();});next.setOnErrorListener((p,a,b)->{stopPlayback();status.setText("음성 파일을 다시 선택하세요");actions();return true;});next.prepareAsync();actions();}catch(Exception e){stopPlayback();status.setText("소리를 재생할 수 없습니다");actions();}}
 private void progress(Job job,String text){main.post(()->{if(active&&!destroyed&&current==job)status.setText(text);});}
 private void accept(Job job,JSONObject value,float[] waveform,double duration){if(destroyed||current!=job)return;current=null;last=value;lastWaveform=waveform;lastDuration=duration;if(active){status.setText("CANCELED".equals(value.optString("state"))?"분석을 중지했습니다":"COMPLETED".equals(value.optString("state"))?"모델 비교 완료":"음성을 다시 선택하거나 다른 모델로 분석하세요");render(value,waveform,duration);}actions();}
 private void render(JSONObject value,float[] waveform,double duration){results.removeAllViews();if(waveform!=null){LinearLayout panel=Ui.panel(this);panel.addView(Ui.heading(this,"입력 파형 · "+String.format(Locale.KOREA,"%.2f초",duration),18));panel.addView(new Waveform(this,waveform,duration),new LinearLayout.LayoutParams(-1,Ui.dp(this,126)));results.addView(panel,spaced());}JSONArray models=value.optJSONArray("models");if(models==null)return;int columns=Ui.contentColumns(this,models.length());LinearLayout row=null;for(int i=0;i<models.length();i++){JSONObject model=models.optJSONObject(i);if(i%columns==0){row=new LinearLayout(this);row.setBaselineAligned(false);results.addView(row,spaced());}LinearLayout card=Ui.panel(this);card.addView(Ui.heading(this,title(model.optString("modelId")),20));card.addView(Ui.pill(this,OneModelReport.state(model.optString("state")),true));card.addView(Ui.text(this,"모델 준비 "+model.optLong("loadMs")+" ms · 분석 "+model.optLong("inferenceMs")+" ms",14));JSONArray top=model.optJSONArray("top5");if(top!=null){card.addView(Ui.heading(this,"전체 구간 평균",16));for(int n=0;n<top.length();n++){JSONObject score=top.optJSONObject(n);card.addView(Ui.text(this,(n+1)+". "+score.optString("label")+" · "+percent(score.optDouble("score")),15));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(1000);bar.setProgress((int)Math.max(0,Math.min(1000,score.optDouble("score")*1000)));card.addView(bar,new LinearLayout.LayoutParams(-1,Ui.dp(this,10)));}}JSONObject quality=model.optJSONObject("metrics");if(quality!=null&&quality.optBoolean("referenceVerified")){card.addView(Ui.text(this,"원본 라벨 · "+quality.optString("reference")+"\nTop1 "+(quality.optBoolean("top1Matched")?"일치":"다른 후보")+" · Top3 "+(quality.optBoolean("top3Matched")?"포함":"미포함"),14));}JSONArray windows=model.optJSONArray("windows");if(windows!=null){card.addView(Ui.heading(this,"시간대별 소리",16));for(int n=0;n<windows.length();n++){JSONObject window=windows.optJSONObject(n);JSONArray scores=window.optJSONArray("top");JSONObject first=scores==null?null:scores.optJSONObject(0);card.addView(Ui.text(this,String.format(Locale.KOREA,"%.2f–%.2f초",window.optDouble("startSec"),window.optDouble("endSec"))+"  "+(first==null?"":first.optString("label")+" · "+percent(first.optDouble("score"))),13));}}if(!model.optString("errorType").isEmpty())card.addView(Ui.text(this,model.optString("errorType"),14));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);if(i%columns>0)cp.leftMargin=Ui.dp(this,12);row.addView(card,cp);} }
 private String title(String id){try{return OneModels.title(this,"sound",id);}catch(Exception e){return id;}}
 private static String percent(double x){return String.format(Locale.KOREA,"%.1f%%",100*x);}
 private LinearLayout.LayoutParams spaced(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=Ui.dp(this,16);return p;}
 private void export(){if(last==null||current!=null||exporting)return;exporting=true;actions();JSONObject snapshot;try{snapshot=new JSONObject(last.toString());}catch(Exception e){exporting=false;actions();return;}List<String> names=new ArrayList<>();JSONArray models=snapshot.optJSONArray("models");for(int i=0;models!=null&&i<models.length();i++)names.add(title(models.optJSONObject(i).optString("modelId")));String label=demoTitle();try{WORK.execute(()->{String error="";try{File directory=new File(getFilesDir(),"exports");if(!directory.isDirectory()&&!directory.mkdirs())throw new IOException("report directory");String prefix="AXSL-Vision-models-"+UUID.randomUUID();OneInputAttribution.Entry credit=OneInputAttribution.find(getApplicationContext(),snapshot.optString("demoId"),snapshot.optString("inputSha256"));if(!credit.empty())snapshot.put("inputAttribution",credit.json());List<OneModelReport.Model> report=new ArrayList<>();List<String[]> csv=new ArrayList<>();for(int i=0;models!=null&&i<models.length();i++){JSONObject source=models.optJSONObject(i);OneModelReport.Model m=new OneModelReport.Model();m.title=names.get(i);m.state=source.optString("state");m.modelSha=source.optString("modelSha256");m.loadMs=source.optLong("loadMs");m.inferenceMs=source.optLong("inferenceMs");m.elapsedMs=source.optLong("elapsedMs");m.summary=source.optString("summary");StringBuilder detail=new StringBuilder();JSONArray candidates=source.optJSONArray("top5");for(int rank=0;candidates!=null&&rank<candidates.length();rank++){JSONObject candidate=candidates.optJSONObject(rank);detail.append(rank+1).append(". ").append(candidate.optString("label")).append(" · 평균 ").append(percent(candidate.optDouble("score"))).append(" · 최고 구간 ").append(percent(candidate.optDouble("peak"))).append("\n");}m.detail=detail.toString();m.metrics.add(new String[]{"입력 길이",String.format(Locale.KOREA,"%.2f초",snapshot.optDouble("durationSec"))});m.metrics.add(new String[]{"분석 창 / 이동", "0.975초 / 0.480초"});m.metrics.add(new String[]{"PCM SHA256",snapshot.optString("pcmSha256")});report.add(m);JSONArray top=source.optJSONArray("top5");for(int j=0;top!=null&&j<top.length();j++){JSONObject score=top.optJSONObject(j);csv.add(new String[]{m.title,Integer.toString(j+1),score.optString("label"),score.optString("score"),score.optString("peak"),Long.toString(m.inferenceMs),snapshot.optString("inputSha256"),snapshot.optString("pcmSha256"),credit.text()});}}String html=OneModelReport.html("생활 소리 분석",label,snapshot.optString("inputSha256"),report,"",credit.text());writeText(new File(directory,prefix+".html"),html);writeText(new File(directory,prefix+".json"),snapshot.toString(2));writeText(new File(directory,prefix+".csv"),OneExportCore.csv(new String[]{"모델","순위","분류","평균 점수","최고 점수","분석 ms","입력 SHA256","PCM SHA256","자료 출처·이용 조건"},csv));OneRunLog.append(getApplicationContext(),new JSONObject().put("type","model-audio-report").put("feature","sound").put("modelId","comparison").put("state","COMPLETED").put("inputSha256",snapshot.optString("inputSha256")).put("demoId",snapshot.optString("demoId")).put("reportPath","exports/"+prefix+".html").put("summary","생활 소리 · 모델 비교 리포트"));}catch(Exception e){error=e.getClass().getSimpleName();}String issue=error;main.post(()->{exporting=false;if(!destroyed){status.setText(issue.isEmpty()?"리포트 저장 완료 · HTML · CSV · JSON":"리포트를 저장할 수 없습니다");actions();}});});}catch(RejectedExecutionException e){exporting=false;status.setText("분석을 마친 뒤 저장하세요");actions();}}
 private static void writeText(File target,String text)throws Exception{File pending=new File(target.getParentFile(),target.getName()+".pending");try{try(FileOutputStream out=new FileOutputStream(pending)){out.write(text.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!pending.renameTo(target))throw new IOException("report commit");}finally{pending.delete();}}
 private static final class Waveform extends View{final float[] values;final double seconds;final Paint pen=new Paint(Paint.ANTI_ALIAS_FLAG);Waveform(Context c,float[] values,double seconds){super(c);this.values=values;this.seconds=seconds;setContentDescription("선택한 실제 음성의 파형과 초 단위 시간축");}protected void onDraw(Canvas canvas){super.onDraw(canvas);float width=getWidth();pen.setTextSize(getResources().getDisplayMetrics().scaledDensity*12);float axis=-pen.getFontMetrics().ascent+pen.getFontMetrics().descent+10,height=Math.max(1,getHeight()-axis),center=height/2;pen.setColor(Ui.BORDER);canvas.drawLine(0,center,width,center,pen);pen.setColor(Ui.ACCENT);pen.setStrokeWidth(Math.max(1,width/values.length*.7f));for(int i=0;i<values.length;i++){float x=(i+.5f)*width/values.length,y=Math.min(1,values[i])*height*.45f;canvas.drawLine(x,center-y,x,center+y,pen);}pen.setColor(Ui.MUTED);pen.setTextSize(getResources().getDisplayMetrics().scaledDensity*12);canvas.drawText("0초",0,getHeight()-4,pen);String end=String.format(Locale.KOREA,"%.2f초",seconds);canvas.drawText(end,Math.max(0,width-pen.measureText(end)),getHeight()-4,pen);}}
 private static final class Job implements Runnable{
  final String id=UUID.randomUUID().toString(),demo,group;final Context app;final WeakReference<SoundBenchActivity> view;final Uri uri;final List<String> ids;final boolean microphone;final AtomicBoolean canceled=new AtomicBoolean();final JSONArray models=new JSONArray();final long started=SystemClock.elapsedRealtime();SoundAudioInput audio;String state="PREPARING",error="";boolean workerDone;Job(Context app,SoundBenchActivity activity,Uri uri,String demo,List<String> ids,boolean microphone){this.app=app;view=new WeakReference<>(activity);this.uri=uri;this.demo=demo;this.group=activity.group;this.ids=ids;this.microphone=microphone;}
  void progress(String text){SoundBenchActivity a=view.get();if(a!=null)a.progress(this,text);}
  JSONObject record(){JSONObject value=new JSONObject();try{value.put("runId",id).put("feature","sound").put("group",group).put("demoId",demo).put("state",state).put("workerDone",workerDone).put("errorType",error).put("models",models).put("elapsedMs",SystemClock.elapsedRealtime()-started).put("playbackClosed",true);if(audio!=null){JSONObject info=audio.json();for(Iterator<String> keys=info.keys();keys.hasNext();){String key=keys.next();value.put(key,info.get(key));}value.put("inputSha256",audio.sourceSha256);}if(LATEST.get().equals(id))Records.write(app,"sound-bench-result.json",value);}catch(Exception e){android.util.Log.w("YOn","sound_record",e);}return value;}
  public void run(){float[] waveform=null;double duration=0;record();try{SoundMath.check(canceled::get);audio=SoundAudioInput.create(app);if(microphone){progress("5초간 주변 소리를 듣습니다");state="LISTENING";audio.microphone(app,canceled::get,()->record());}else audio.prepare(app,uri,canceled::get);duration=audio.pcm.length/16000d;waveform=SoundMath.waveform(audio.pcm,420);state="RUNNING";record();for(String model:ids){SoundMath.check(canceled::get);SoundEngine engine=null;JSONObject result=new JSONObject().put("modelId",model).put("state","ERROR");long start=SystemClock.elapsedRealtime();boolean engineClosed=true;try{progress((models.length()+1)+" / "+ids.size()+" 모델 분석 중");engineClosed=false;engine=new SoundEngine(app,model,canceled::get);result=engine.analyze(audio.pcm,audio.sourcePcm,audio.sourceRate,canceled::get);SoundMath.check(canceled::get);quality(result);JSONArray top=result.optJSONArray("top5");String summary=top==null||top.length()==0?"소리 후보 없음":top.optJSONObject(0).optString("label")+" · 평균 "+percent(top.optJSONObject(0).optDouble("score"));result.put("summary",summary);}catch(Exception|LinkageError|OutOfMemoryError e){result.put("state",canceled.get()?"CANCELED":"ERROR").put("errorType",e.getClass().getSimpleName());}finally{try{if(engine!=null)engine.close();engineClosed=engine==null||engine.closed();}catch(Exception|LinkageError e){engineClosed=false;result.put("state","ERROR").put("cleanupErrorType",e.getClass().getSimpleName());}result.put("engineCloseReturned",engineClosed).put("elapsedMs",SystemClock.elapsedRealtime()-start).put("inputSha256",audio.sourceSha256).put("inputPcmSha256",audio.pcmSha256).put("group",group);models.put(result);OneRunLog.append(app,new JSONObject(result.toString()).put("type","model-audio-comparison").put("feature","sound").put("group",group).put("demoId",demo).put("runId",id));record();}}state=canceled.get()?"CANCELED":"COMPLETED";for(int i=0;i<models.length();i++)if(!"COMPLETED".equals(models.optJSONObject(i).optString("state"))&&!canceled.get())state="ERROR";}catch(Exception|LinkageError|OutOfMemoryError e){state=canceled.get()?"CANCELED":"ERROR";error=e.getClass().getSimpleName();}finally{if(audio!=null)try{audio.close();}catch(Exception e){state="ERROR";error="InputCleanup";}workerDone=true;JSONObject result=record();float[] drawing=waveform;double seconds=duration;new Handler(Looper.getMainLooper()).post(()->{SoundBenchActivity activity=view.get();if(activity!=null)activity.accept(this,result,drawing,seconds);});}}
  private void quality(JSONObject result)throws Exception{JSONObject expected=null;try(InputStream in=app.getAssets().open("one/demos.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);JSONArray items=new JSONObject(out.toString("UTF-8")).getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);if(demo.equals(item.getString("id"))&&audio.sourceSha256.equals(item.getString("sha256"))){expected=item.optJSONObject("soundExpected");break;}}}if(expected==null)return;JSONArray names=expected.optJSONArray("audioSetLabels"),top=result.optJSONArray("top5");if(names==null||names.length()==0||top==null)return;Set<String> aliases=new HashSet<>();for(int i=0;i<names.length();i++)aliases.add(names.getString(i));boolean top1=false,top3=false;for(int i=0;i<Math.min(3,top.length());i++)if(aliases.contains(top.getJSONObject(i).getString("label"))){top3=true;if(i==0)top1=true;}result.put("metrics",new JSONObject().put("referenceVerified",true).put("reference",expected.optString("escCategory",expected.optBoolean("negative")?"Silence":"")).put("referenceLabels",names).put("top1Matched",top1).put("top3Matched",top3).put("evaluationScope","This labeled clip only; accepted AudioSet-label aliases are from publisher ontology mapping, not model output."));}
 }
